    private int size;

    void add(int value) {
        if (size == elements.length) {
            elements = Arrays.copyOf(elements, elements.length * 2);
        }
        elements[size++] = value;
    }

    int get(int index) {
        if (index < 0 || index >= size) throw new IndexOutOfBoundsException(index);
        return elements[index];
    }

    int size() {
        return size;
    }

    int capacity() {
        return elements.length;
    }
}

