import java.util.*;

public class Solution {}

final class Candidate implements Comparable<Candidate> {
    private final String name;
    private final int score;

    Candidate(String name, int score) {
        this.name = name;
        this.score = score;
    }

    String name() {
        return name;
    }

    int score() {
        return score;
    }

    @Override
    public int compareTo(Candidate other) {
        return name.compareTo(other.name);
    }
}

final class CandidateOrder {
    static Comparator<Candidate> byScoreThenName() {
        return Comparator.comparingInt(Candidate::score)
                .reversed()
                .thenComparing(Candidate::name);
    }
}

